"""Synthetic fixtures only: fixed LOCAL Docker socket/container/database; no remote fallback."""
import subprocess,json,uuid,concurrent.futures
base=['docker','--host=unix:///var/run/docker.sock','exec','-i','hm-stripe-db','psql','-U','postgres','-d','hm_stripe_final','-v','ON_ERROR_STOP=1','-tA']
def sql(s):return subprocess.check_output(base,input=s,text=True).strip()
bid=str(uuid.uuid4());actor=str(uuid.uuid4());digest=uuid.uuid4().hex+uuid.uuid4().hex
sql(f"insert into auth.users(id) values('{actor}'); insert into public.admins values('{actor}'); insert into public.consultation_bookings(id,package_type,price_cents,duration_minutes,customer_name,email,consultation_language,preferred_local,preferred_timezone,preferred_at,terms_version,privacy_version,request_fingerprint) values('{bid}','expert',9900,60,'Synthetic Person','synthetic@example.test','en',now()+interval '10 days','UTC',now()+interval '10 days','consultation-2026-11-11-draft-1','privacy-2026-11-11-draft-1',repeat('a',64));")
a=json.loads(sql(f"select public.consultation_payment_command('invite','{bid}','{digest}','{actor}');"));aid=a['id']
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 results=list(pool.map(lambda _:json.loads(sql(f"select public.consultation_payment_command('reserve',null,'{digest}');")),range(8)))
assert len({r['id'] for r in results})==1
assert len({r['checkout_started_at'] for r in results})==1
suffix=uuid.uuid4().hex
payload=json.dumps({'event_id':'evt_concurrent_'+suffix,'kind':'payment','next':'paid','session_id':'cs_test_'+suffix,'intent_id':'pi_'+suffix,'amount':9900,'currency':'usd'})
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 list(pool.map(lambda _:sql(f"select public.consultation_payment_command('event','{aid}',null,null,'{payload}'::jsonb);"),range(8)))
assert sql(f"select count(*) from public.consultation_payment_events where attempt_id='{aid}';")=='1'
assert sql(f"select booking_status||'/'||payment_status from public.consultation_bookings where id='{bid}';")=='requested/paid'
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 refunds=list(pool.map(lambda _:json.loads(sql(f"select public.consultation_payment_command('refund_reserve','{bid}',null,'{actor}');")),range(8)))
assert len({r['id'] for r in refunds})==1
# Separate explicit admin confirmation succeeds only on its own endpoint/command.
sql(f"select public.consultation_payment_command('confirm','{bid}',null,'{actor}');")
assert sql(f"select booking_status from public.consultation_bookings where id='{bid}';")=='confirmed'
print(json.dumps({'parallelCheckoutReservations':8,'distinctCheckoutOperations':1,'parallelDuplicatePaidEvents':8,'processedPaidEvents':1,'parallelRefundReservations':8,'distinctRefundOperations':1,'appointmentStayedRequestedUntilSeparateConfirmation':True}))

